//! CLI argument parser library for gunbc tools.
//!
//! Provides a schema-driven parser that mirrors the argument-parsing logic
//! generated by `cli_gen.rs`. Contract tests can call `parse()` directly
//! instead of spawning subprocesses.

mod binary_args;
pub use binary_args::*;

use std::collections::HashMap;

use gunbc_ir::{Cardinality, NamingCase, Value};

/// The type of a CLI parameter.
///
/// Provides compile-time safety instead of stringly-typed `"Bool"` / `"Int"` / `"String"`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ParamType {
    Str,
    Int,
    Bool,
}

impl ParamType {
    /// String representation matching the IR type system names.
    pub fn as_str(&self) -> &'static str {
        match self {
            Self::Str => "String",
            Self::Int => "Int",
            Self::Bool => "Bool",
        }
    }
}

/// Parse error for `ParamType`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ParamTypeParseError {
    value: String,
}

impl std::fmt::Display for ParamTypeParseError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(
            f,
            "unknown ParamType '{}'; expected String/Str, Int, or Bool",
            self.value
        )
    }
}

impl std::error::Error for ParamTypeParseError {}

impl TryFrom<&str> for ParamType {
    type Error = ParamTypeParseError;

    fn try_from(s: &str) -> Result<Self, Self::Error> {
        match s {
            "String" | "Str" => Ok(Self::Str),
            "Bool" => Ok(Self::Bool),
            "Int" => Ok(Self::Int),
            other => Err(ParamTypeParseError {
                value: other.to_string(),
            }),
        }
    }
}

impl std::fmt::Display for ParamType {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(self.as_str())
    }
}

/// Describes a single CLI parameter (flag).
#[derive(Debug, Clone)]
pub struct CliParam {
    /// Port name in snake_case (e.g., "repo_path").
    pub port_name: String,
    /// The type of this parameter.
    pub type_id: ParamType,
    /// Cardinality — scalar vs repeatable.
    pub cardinality: Cardinality,
    /// Optional short flag character (e.g., 'r' for `-r`).
    pub short_flag: Option<char>,
    /// Default value as a string, if any.
    pub default_value: Option<String>,
}

impl CliParam {
    /// Create a new CLI param with default `Cardinality::ONE`.
    pub fn new(port_name: impl Into<String>, type_id: ParamType) -> Self {
        Self {
            port_name: port_name.into(),
            type_id,
            cardinality: Cardinality::ONE,
            short_flag: None,
            default_value: None,
        }
    }

    /// Set cardinality.
    pub fn with_cardinality(mut self, c: Cardinality) -> Self {
        self.cardinality = c;
        self
    }

    /// Set short flag.
    pub fn short(mut self, c: char) -> Self {
        self.short_flag = Some(c);
        self
    }

    /// Set default value.
    pub fn default(mut self, val: impl Into<String>) -> Self {
        self.default_value = Some(val.into());
        self
    }

    /// Whether this param accepts multiple values (repeatable flag).
    pub fn is_repeatable(&self) -> bool {
        self.cardinality.allows_many()
    }

    /// Derive the long flag name from port_name (kebab-case).
    pub fn flag_name(&self) -> String {
        NamingCase::KebabCase.apply(&self.port_name)
    }
}

/// Result of parsing CLI arguments.
#[derive(Debug)]
pub struct ParseResult {
    /// Parsed values keyed by port_name.
    pub values: HashMap<String, Value>,
    /// Whether `--dry-run` / `-n` was present.
    pub dry_run: bool,
    /// Whether `--help` / `-h` was present.
    pub help: bool,
}

/// Errors that can occur during CLI parsing.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ParseError {
    /// A required parameter was not provided.
    MissingRequired { port_name: String },
    /// A flag that expects a value had no following argument.
    MissingValue { flag: String },
    /// An integer flag received a non-integer value.
    InvalidInt { flag: String, value: String },
    /// An unrecognized flag was provided.
    UnknownFlag { flag: String },
    /// A flag received an invalid value.
    InvalidValue { flag: String, value: String },
}

impl std::fmt::Display for ParseError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ParseError::MissingRequired { port_name } => {
                write!(
                    f,
                    "missing required argument: --{}",
                    NamingCase::KebabCase.apply(port_name)
                )
            }
            ParseError::MissingValue { flag } => {
                write!(f, "flag '{}' requires a value", flag)
            }
            ParseError::InvalidInt { flag, value } => {
                write!(f, "flag '{}' expects an integer, got '{}'", flag, value)
            }
            ParseError::UnknownFlag { flag } => {
                write!(f, "unknown flag '{}'", flag)
            }
            ParseError::InvalidValue { flag, value } => {
                write!(f, "invalid value '{}' for flag '{}'", value, flag)
            }
        }
    }
}

impl std::error::Error for ParseError {}

/// Parse an i64 value for a CLI flag using canonical error semantics.
pub fn parse_int_flag(flag: &str, value: &str) -> Result<i64, ParseError> {
    value.parse::<i64>().map_err(|_| ParseError::InvalidInt {
        flag: flag.to_string(),
        value: value.to_string(),
    })
}

/// Parse CLI arguments against a schema.
///
/// Implements the same while-loop logic that `cli_gen.rs` generates inline:
/// - Bool params: presence flag (no value consumed)
/// - String/Int params: consume next arg
/// - Repeatable (`cardinality.allows_many()`): push to `Value::List`
/// - Defaults applied for missing optional params
/// - `--dry-run` / `-n` and `--help` / `-h` are built-in
/// - Unknown flags return `ParseError::UnknownFlag`
///
/// `argv` should include the program name at index 0 (it is skipped).
pub fn parse(argv: &[String], schema: &[CliParam]) -> Result<ParseResult, ParseError> {
    // Build lookup: flag string → index into schema
    let mut flag_map: HashMap<String, usize> = HashMap::new();
    for (idx, param) in schema.iter().enumerate() {
        let long = format!("--{}", param.flag_name());
        flag_map.insert(long, idx);
        if let Some(c) = param.short_flag {
            flag_map.insert(format!("-{}", c), idx);
        }
    }

    // Initialize accumulators
    let mut scalars: HashMap<usize, Option<String>> = HashMap::new();
    let mut lists: HashMap<usize, Vec<String>> = HashMap::new();
    for (idx, param) in schema.iter().enumerate() {
        if param.is_repeatable() {
            lists.insert(idx, Vec::new());
        } else {
            scalars.insert(idx, param.default_value.clone());
        }
    }

    let mut dry_run = false;
    let mut help = false;

    // Parse loop — skip argv[0] (program name)
    let mut i = 1;
    while i < argv.len() {
        let arg = &argv[i];
        match arg.as_str() {
            "-n" | "--dry-run" => dry_run = true,
            "-h" | "--help" => help = true,
            _ => {
                let (flag, inline_value) = match arg.split_once('=') {
                    Some((f, v)) if f.starts_with('-') => (f, Some(v)),
                    _ => (arg.as_str(), None),
                };

                if let Some(&idx) = flag_map.get(flag) {
                    let param = &schema[idx];
                    if param.type_id == ParamType::Bool && !param.is_repeatable() {
                        let bool_value = match inline_value {
                            Some("true") => "true",
                            Some("false") => "false",
                            Some(v) => {
                                return Err(ParseError::InvalidValue {
                                    flag: flag.to_string(),
                                    value: v.to_string(),
                                });
                            }
                            None => "true",
                        };
                        scalars.insert(idx, Some(bool_value.to_string()));
                    } else if param.is_repeatable() {
                        let value = if let Some(v) = inline_value {
                            v.to_string()
                        } else {
                            i += 1;
                            if i >= argv.len() {
                                return Err(ParseError::MissingValue {
                                    flag: flag.to_string(),
                                });
                            }
                            argv[i].clone()
                        };
                        lists.get_mut(&idx).unwrap().push(value);
                    } else {
                        let value = if let Some(v) = inline_value {
                            v.to_string()
                        } else {
                            i += 1;
                            if i >= argv.len() {
                                return Err(ParseError::MissingValue {
                                    flag: flag.to_string(),
                                });
                            }
                            argv[i].clone()
                        };
                        scalars.insert(idx, Some(value));
                    }
                } else if arg.starts_with('-') {
                    return Err(ParseError::UnknownFlag { flag: arg.clone() });
                }
            }
        }
        i += 1;
    }

    // Build result values
    let mut values: HashMap<String, Value> = HashMap::new();

    for (idx, param) in schema.iter().enumerate() {
        if param.is_repeatable() {
            let items = lists.remove(&idx).unwrap_or_default();
            if !items.is_empty() {
                values.insert(param.port_name.clone(), Value::str_list(items));
            }
        } else {
            match scalars.get(&idx) {
                Some(Some(val)) => {
                    let value = match param.type_id {
                        ParamType::Bool => Value::Bool(val == "true"),
                        ParamType::Int => Value::Int(parse_int_flag(&param.flag_name(), val)?),
                        ParamType::Str => Value::Str(val.clone()),
                    };
                    values.insert(param.port_name.clone(), value);
                }
                _ => {
                    // No value and no default — check if required
                    if param.cardinality.requires_one() && param.default_value.is_none() {
                        // Bool defaults to false (not missing)
                        if param.type_id == ParamType::Bool {
                            values.insert(param.port_name.clone(), Value::Bool(false));
                        }
                        // String/Int with no default: not present in values
                        // (matches generated CLI behavior where Option<String> = None)
                    }
                }
            }
        }
    }

    Ok(ParseResult {
        values,
        dry_run,
        help,
    })
}

/// Format a Value for CLI header display.
///
/// Matches the println! format of generated CLIs so that output is identical
/// whether inline variables or parsed values are used.
pub fn format_value(value: &Value) -> String {
    match value {
        Value::Str(s) => s.clone(),
        Value::Int(i) => i.to_string(),
        Value::Bool(b) => b.to_string(),
        Value::List(items) => format!("{:?}", items.iter().map(format_value).collect::<Vec<_>>()),
        _ => format!("{:?}", value),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn argv(args: &[&str]) -> Vec<String> {
        args.iter().map(|s| s.to_string()).collect()
    }

    #[test]
    fn test_string_param() {
        let schema = vec![CliParam::new("repo_path", ParamType::Str)];
        let result = parse(&argv(&["prog", "--repo-path", "my-repo"]), &schema).unwrap();
        assert_eq!(result.values["repo_path"], Value::Str("my-repo".into()));
    }

    #[test]
    fn test_int_param() {
        let schema = vec![CliParam::new("count", ParamType::Int)];
        let result = parse(&argv(&["prog", "--count", "42"]), &schema).unwrap();
        assert_eq!(result.values["count"], Value::Int(42));
    }

    #[test]
    fn test_bool_param() {
        let schema = vec![CliParam::new("public", ParamType::Bool)];
        let result = parse(&argv(&["prog", "--public"]), &schema).unwrap();
        assert_eq!(result.values["public"], Value::Bool(true));
    }

    #[test]
    fn test_bool_absent() {
        let schema = vec![CliParam::new("public", ParamType::Bool)];
        let result = parse(&argv(&["prog"]), &schema).unwrap();
        assert_eq!(result.values["public"], Value::Bool(false));
    }

    #[test]
    fn test_repeatable_param() {
        let schema =
            vec![CliParam::new("extensions", ParamType::Str)
                .with_cardinality(Cardinality::ZERO_OR_MORE)];
        let result = parse(
            &argv(&["prog", "--extensions", ".rs", "--extensions", ".toml"]),
            &schema,
        )
        .unwrap();
        assert_eq!(
            result.values["extensions"],
            Value::str_list(vec![".rs".into(), ".toml".into()])
        );
    }

    #[test]
    fn test_repeatable_empty() {
        let schema =
            vec![CliParam::new("extensions", ParamType::Str)
                .with_cardinality(Cardinality::ZERO_OR_MORE)];
        let result = parse(&argv(&["prog"]), &schema).unwrap();
        assert!(!result.values.contains_key("extensions"));
    }

    #[test]
    fn test_default_value() {
        let schema = vec![CliParam::new("repo_path", ParamType::Str).default(".")];
        let result = parse(&argv(&["prog"]), &schema).unwrap();
        assert_eq!(result.values["repo_path"], Value::Str(".".into()));
    }

    #[test]
    fn test_default_overridden() {
        let schema = vec![CliParam::new("repo_path", ParamType::Str).default(".")];
        let result = parse(&argv(&["prog", "--repo-path", "other"]), &schema).unwrap();
        assert_eq!(result.values["repo_path"], Value::Str("other".into()));
    }

    #[test]
    fn test_short_flag() {
        let schema = vec![CliParam::new("repo_path", ParamType::Str).short('r')];
        let result = parse(&argv(&["prog", "-r", "my-repo"]), &schema).unwrap();
        assert_eq!(result.values["repo_path"], Value::Str("my-repo".into()));
    }

    #[test]
    fn test_dry_run() {
        let schema = vec![];
        let result = parse(&argv(&["prog", "--dry-run"]), &schema).unwrap();
        assert!(result.dry_run);
        assert!(!result.help);
    }

    #[test]
    fn test_dry_run_short() {
        let schema = vec![];
        let result = parse(&argv(&["prog", "-n"]), &schema).unwrap();
        assert!(result.dry_run);
    }

    #[test]
    fn test_help() {
        let schema = vec![];
        let result = parse(&argv(&["prog", "--help"]), &schema).unwrap();
        assert!(result.help);
        assert!(!result.dry_run);
    }

    #[test]
    fn test_help_short() {
        let schema = vec![];
        let result = parse(&argv(&["prog", "-h"]), &schema).unwrap();
        assert!(result.help);
    }

    #[test]
    fn test_unknown_flags_error() {
        let schema = vec![CliParam::new("repo_path", ParamType::Str)];
        let result = parse(
            &argv(&["prog", "--unknown", "val", "--repo-path", "my-repo"]),
            &schema,
        );
        assert!(result.is_err());
        assert_eq!(
            result.unwrap_err(),
            ParseError::UnknownFlag {
                flag: "--unknown".to_string()
            }
        );
    }

    #[test]
    fn test_empty_argv() {
        let schema = vec![CliParam::new("repo_path", ParamType::Str).default(".")];
        let result = parse(&argv(&["prog"]), &schema).unwrap();
        assert_eq!(result.values["repo_path"], Value::Str(".".into()));
        assert!(!result.dry_run);
        assert!(!result.help);
    }

    #[test]
    fn test_kebab_case_flag_names() {
        let schema = vec![CliParam::new("base_ref", ParamType::Str)];
        let result = parse(&argv(&["prog", "--base-ref", "main"]), &schema).unwrap();
        assert_eq!(result.values["base_ref"], Value::Str("main".into()));
    }

    #[test]
    fn test_invalid_int_returns_error() {
        let schema = vec![CliParam::new("count", ParamType::Int)];
        let result = parse(&argv(&["prog", "--count", "not-a-number"]), &schema);
        assert!(result.is_err());
        assert_eq!(
            result.unwrap_err(),
            ParseError::InvalidInt {
                flag: "count".to_string(),
                value: "not-a-number".to_string()
            }
        );
    }

    #[test]
    fn test_multiple_params() {
        let schema = vec![
            CliParam::new("repo_path", ParamType::Str)
                .short('r')
                .default("."),
            CliParam::new("public", ParamType::Bool),
            CliParam::new("extensions", ParamType::Str).with_cardinality(Cardinality::ZERO_OR_MORE),
        ];
        let result = parse(
            &argv(&[
                "prog",
                "--dry-run",
                "--repo-path",
                "test-repo",
                "--extensions",
                ".rs",
                "--extensions",
                ".toml",
                "--public",
            ]),
            &schema,
        )
        .unwrap();
        assert!(result.dry_run);
        assert_eq!(result.values["repo_path"], Value::Str("test-repo".into()));
        assert_eq!(result.values["public"], Value::Bool(true));
        assert_eq!(
            result.values["extensions"],
            Value::str_list(vec![".rs".into(), ".toml".into()])
        );
    }

    #[test]
    fn test_string_no_default_absent() {
        let schema = vec![CliParam::new("repo_path", ParamType::Str)];
        let result = parse(&argv(&["prog"]), &schema).unwrap();
        assert!(!result.values.contains_key("repo_path"));
    }

    #[test]
    fn test_int_default() {
        let schema = vec![CliParam::new("count", ParamType::Int).default("10")];
        let result = parse(&argv(&["prog"]), &schema).unwrap();
        assert_eq!(result.values["count"], Value::Int(10));
    }

    #[test]
    fn test_param_type_try_from() {
        assert_eq!(ParamType::try_from("String").unwrap(), ParamType::Str);
        assert_eq!(ParamType::try_from("Int").unwrap(), ParamType::Int);
        assert_eq!(ParamType::try_from("Bool").unwrap(), ParamType::Bool);
    }

    #[test]
    fn test_param_type_try_from_invalid() {
        let err = ParamType::try_from("Json").unwrap_err();
        assert!(err.to_string().contains("unknown ParamType"));
    }

    #[test]
    fn test_equals_syntax_for_scalar_flag() {
        let schema = vec![CliParam::new("count", ParamType::Int)];
        let result = parse(&argv(&["prog", "--count=7"]), &schema).unwrap();
        assert_eq!(result.values["count"], Value::Int(7));
    }

    #[test]
    fn test_missing_value_errors_for_scalar() {
        let schema = vec![CliParam::new("repo_path", ParamType::Str)];
        let result = parse(&argv(&["prog", "--repo-path"]), &schema);
        assert!(matches!(result, Err(ParseError::MissingValue { .. })));
    }

    #[test]
    fn test_missing_value_errors_for_repeatable() {
        let schema =
            vec![CliParam::new("extensions", ParamType::Str)
                .with_cardinality(Cardinality::ZERO_OR_MORE)];
        let result = parse(&argv(&["prog", "--extensions"]), &schema);
        assert!(matches!(result, Err(ParseError::MissingValue { .. })));
    }

    #[test]
    fn test_bool_equals_rejects_invalid_value() {
        let schema = vec![CliParam::new("public", ParamType::Bool)];
        let result = parse(&argv(&["prog", "--public=maybe"]), &schema);
        assert!(matches!(result, Err(ParseError::InvalidValue { .. })));
    }

    #[test]
    fn test_parse_int_flag_success() {
        assert_eq!(parse_int_flag("count", "12").unwrap(), 12);
    }

    #[test]
    fn test_parse_int_flag_error() {
        assert!(matches!(
            parse_int_flag("count", "x"),
            Err(ParseError::InvalidInt { .. })
        ));
    }
}
